// 🧪 BOTI'S DIAGNOSTICS — week 2
//
// ⚠️ Do not edit this file. These are Doña Carmen's exact orders.
// Red = the skill is not installed yet. Green = installed!
//
// Run the diagnostics with:   npm run week2

const {
  getProduct,
  getPrice,
  isInStock,
  getBasketTotal,
  applyDiscount,
  makeDiscountedCopy,
  parseShopQuery,
  filterByCategory,
  getCheapestProduct,
  makeReport,
} = require("./skills");
const { products } = require("./bodega");

// 📖 Q1 — Read the ledger ----------------------------------------

test("Q1: finds the tortilla's line in the ledger", () => {
  const currentOutput = getProduct(products, "tortilla");
  const targetOutput = {
    name: "tortilla",
    price: 3.25,
    stock: 4,
    emoji: "🥘",
    category: "food",
  };
  expect(currentOutput).toEqual(targetOutput);
});

test("Q1: a product that doesn't exist is undefined", () => {
  expect(getProduct(products, "caviar")).toEqual(undefined);
});

// 🏷️ Q2 — Price check --------------------------------------------

test("Q2: tells us the price of a product", () => {
  expect(getPrice(products, "tortilla")).toEqual(3.25);
});

test("Q2: the price of a product that doesn't exist is undefined", () => {
  expect(getPrice(products, "caviar")).toEqual(undefined);
});

// 😤 Q3 — The picky customer --------------------------------------

test("Q3: says a stocked product is in stock", () => {
  expect(isInStock(products, "tortilla")).toEqual(true);
});

test("Q3: says churros are sold out (stock is 0)", () => {
  expect(isInStock(products, "churros")).toEqual(false);
});

test("Q3: a product that doesn't exist is not in stock either", () => {
  expect(isInStock(products, "caviar")).toEqual(false);
});

// 🛒 Q4 — Basket run ----------------------------------------------

test("Q4: totals a basket of product names", () => {
  const basket = ["tortilla", "agua", "croissant"];
  expect(getBasketTotal(products, basket)).toEqual(5.75);
});

test("Q4: an empty basket totals 0", () => {
  expect(getBasketTotal(products, [])).toEqual(0);
});

// 💸 Q5a — Happy hour ----------------------------------------------

test("Q5a: happy hour CHANGES the price on the real product", () => {
  const bocadillo = {
    name: "bocadillo",
    price: 4.5,
    stock: 5,
    emoji: "🥪",
    category: "food",
  };
  applyDiscount(bocadillo, 50);
  expect(bocadillo.price).toEqual(2.25);
});

test("Q5a: returns the very same product it was given", () => {
  const ensaimada = {
    name: "ensaimada",
    price: 2.25,
    stock: 6,
    emoji: "🌀",
    category: "bakery",
  };
  const result = applyDiscount(ensaimada, 50);
  // toBe is stricter than toEqual: it checks the value is THE
  // SAME thing in memory — the very same object, not a twin.
  expect(result).toBe(ensaimada);
});

// 🎟️ Q5b — The coupon ----------------------------------------------

test("Q5b: a coupon is a NEW object with the discounted price", () => {
  const cafe = {
    name: "café con leche",
    price: 1.5,
    stock: 20,
    emoji: "☕",
    category: "drinks",
  };
  const coupon = makeDiscountedCopy(cafe, 50);
  expect(coupon).toEqual({
    name: "café con leche",
    price: 0.75,
    stock: 20,
    emoji: "☕",
    category: "drinks",
  });
});

test("Q5b: the real product is untouched — no phantom discounts", () => {
  const cafe = {
    name: "café con leche",
    price: 1.5,
    stock: 20,
    emoji: "☕",
    category: "drinks",
  };
  makeDiscountedCopy(cafe, 50);
  expect(cafe.price).toEqual(1.5);
});

test("Q5b: the coupon is a twin, not the same jar", () => {
  const cafe = {
    name: "café con leche",
    price: 1.5,
    stock: 20,
    emoji: "☕",
    category: "drinks",
  };
  const coupon = makeDiscountedCopy(cafe, 50);
  expect(coupon).not.toBe(cafe);
});

// 🔎 Q6 — The search bar -------------------------------------------

test("Q6: a query string with no parameters gives an empty object", () => {
  expect(parseShopQuery("")).toEqual({});
});

test("Q6: parses one parameter into an object", () => {
  expect(parseShopQuery("category=drinks")).toEqual({ category: "drinks" });
});

test("Q6: parses multiple parameters into an object", () => {
  expect(parseShopQuery("category=drinks&max=2")).toEqual({
    category: "drinks",
    max: "2",
  });
});

// 🧹 Q7 — Tidy the shelves -----------------------------------------

test("Q7: picks out the products of one category", () => {
  expect(filterByCategory(products, "snacks")).toEqual([
    { name: "olives", price: 2.0, stock: 15, emoji: "🫒", category: "snacks" },
    {
      name: "gominolas",
      price: 1.0,
      stock: 9,
      emoji: "🍬",
      category: "snacks",
    },
  ]);
});

test("Q7: a category with no products gives an empty array", () => {
  expect(filterByCategory(products, "toys")).toEqual([]);
});

test("Q7: the ledger stays exactly as it was", () => {
  const before = products.length;
  filterByCategory(products, "drinks");
  expect(products.length).toEqual(before);
  expect(products[0].name).toEqual("tortilla");
});

// 🏆 Q8a — BOSS part 1 ---------------------------------------------

test("Q8a: finds the cheapest product in the shop", () => {
  const stock = [
    { name: "bocadillo", price: 4.5, stock: 5 },
    { name: "agua", price: 0.75, stock: 24 },
    { name: "croissant", price: 1.75, stock: 8 },
  ];
  const cheapest = getCheapestProduct(stock);
  expect(cheapest.name).toEqual("agua");
  expect(cheapest.price).toEqual(0.75);
});

// 🏆 Q8b — BOSS part 2: The MegaMercado audit ----------------------

test("Q8b: builds the business report for the audit", () => {
  const stock = [
    { name: "agua", price: 0.75, stock: 4 },
    { name: "tortilla", price: 3.25, stock: 2 },
    { name: "croissant", price: 1.75, stock: 6 },
  ];
  const targetOutput = {
    itemCount: 3, // 0.75×4 + 3.25×2 + 1.75×6 = 3 + 6.5 + 10.5
    totalValue: 20,
    cheapest: "agua",
  };
  expect(makeReport(stock)).toEqual(targetOutput);
});

test("Q8b: an empty shop reports zeros and no cheapest product", () => {
  expect(makeReport([])).toEqual({
    itemCount: 0,
    totalValue: 0,
    cheapest: undefined,
  });
});
